classDiagram
    class Shape {
        +String name
        +area() float
    }
    class Circle {
        +float radius
        +area() float
    }
    class Drawable {
        <<interface>>
        +draw()
    }
    Shape <|-- Circle
    Drawable <|.. Circle

---
config:
  theme: neo
---
classDiagram
    namespace Model {
        class Document {
            +String name
            +String source
        }
        class Appearance {
            +String schemeName
            +String density
        }
    }
    class Logger {
        <<singleton>>
        +log(msg)
    }
    Document --> Appearance : resolved by
    Document ..> Logger : annotates
    note for Document "keeps the raw user text"

erDiagram
    DOCUMENT ||--o{ REVISION : has
    DOCUMENT {
        string name
        string source
    }
    REVISION {
        int number
        string savedAt
    }
    USER ||--o{ DOCUMENT : owns

---
config:
  theme: neo
---
erDiagram
    USER ||--o{ DOCUMENT : authors
    DOCUMENT }o--o{ TAG : carries
    DOCUMENT {
        string name "filename stem"
        string diagramType "detected by the parser"
    }
    TAG {
        string label
    }
    USER {
        string id PK
        string handle
    }
